34	func newIntegrationTestConfig() *integrationTestConfig {
35		getDefaultEnvValues := func(key, defaultValue string) string {
36			value := os.Getenv(key)
37			if value == "" {
38				return defaultValue
39			}
40			return value
41		}
42	
43		return &integrationTestConfig{
44			testBaseURL:           getDefaultEnvValues("TEST_MINIFLUX_BASE_URL", ""),
45			testAdminUsername:     getDefaultEnvValues("TEST_MINIFLUX_ADMIN_USERNAME", ""),
46			testAdminPassword:     getDefaultEnvValues("TEST_MINIFLUX_ADMIN_PASSWORD", ""),
47			testRegularUsername:   getDefaultEnvValues("TEST_MINIFLUX_REGULAR_USERNAME_PREFIX", "regular_test_user"),
48			testRegularPassword:   getDefaultEnvValues("TEST_MINIFLUX_REGULAR_PASSWORD", "regular_test_user_password"),
49			testFeedURL:           getDefaultEnvValues("TEST_MINIFLUX_FEED_URL", "https://miniflux.app/feed.xml"),
50			testFeedTitle:         getDefaultEnvValues("TEST_MINIFLUX_FEED_TITLE", "Miniflux"),
51			testSubscriptionTitle: getDefaultEnvValues("TEST_MINIFLUX_SUBSCRIPTION_TITLE", "Miniflux Releases"),
52			testWebsiteURL:        getDefaultEnvValues("TEST_MINIFLUX_WEBSITE_URL", "https://miniflux.app/"),
53		}
54	}
55	
56	func (c *integrationTestConfig) isConfigured() bool {
57		return c.testBaseURL != "" && c.testAdminUsername != "" && c.testAdminPassword != "" && c.testFeedURL != "" && c.testFeedTitle != "" && c.testSubscriptionTitle != "" && c.testWebsiteURL != ""
58	}
59	
60	func (c *integrationTestConfig) genRandomUsername() string {
61		return fmt.Sprintf("%s_%10d", c.testRegularUsername, rand.Int())
62	}
