64	func TestIncorrectEndpoint(t *testing.T) {
65		t.Parallel()
66	
67		testConfig := newIntegrationTestConfig()
68		if !testConfig.isConfigured() {
69			t.Skip(skipIntegrationTestsMessage)
70		}
71	
72		client := miniflux.NewClient("incorrect url")
73		if _, err := client.Users(); err == nil {
