262	
263	func (h *handler) removeFeedHandler(w http.ResponseWriter, r *http.Request) {
264		feedID := request.RouteInt64Param(r, "feedID")
265		if feedID == 0 {
266			response.JSONBadRequest(w, r, errors.New("invalid feed ID"))
