94	func (h *handler) refreshAllFeedsHandler(w http.ResponseWriter, r *http.Request) {
95		userID := request.UserID(r)
96	
97		jobs, err := h.store.NewBatchBuilder().
98			WithErrorLimit(config.Opts.PollingParsingErrorLimit()).
99			WithoutDisabledFeeds().
100			WithNextCheckExpired().
101			WithUserID(userID).
102			WithLimitPerHost(config.Opts.PollingLimitPerHost()).
103			FetchJobs()
104		if err != nil {
105			response.JSONServerError(w, r, err)
106			return
107		}
108	
109		slog.Info(
110			"Triggered a manual refresh of all feeds from the API",
111			slog.Int64("user_id", userID),
112			slog.Int("nb_jobs", len(jobs)),
113		)
114	
115		go h.pool.Push(jobs)
116	
117		response.NoContent(w, r)
118	}
