func (s *Storage) RemoveUser(userID int64) error {
	if s.audit == nil {
		if _, err := s.db.Exec(`DELETE FROM users WHERE id=$1`, userID); err != nil {
			return fmt.Errorf(`store: unable to remove user #%d: %v`, userID, err)
		}
		return nil
	}

	tx, err := s.db.Begin()
	if err != nil {
		return fmt.Errorf(`store: unable to start transaction: %v`, err)
	}

	// The user's feeds would be deleted by the foreign key cascade: delete
	// them explicitly so that each removed row can be audited.
	feedIDs, err := queryIDs(tx, `DELETE FROM feeds WHERE user_id=$1 RETURNING id`, userID)
	if err != nil {
