8	
9		"miniflux.app/v2/internal/model"
10		"miniflux.app/v2/internal/storage"
11	)
12	
13	// Pool manages a set of background workers that process feed refresh jobs.
14	type Pool struct {
15		queue        chan model.Job
16		shutdown     chan struct{}
17		shutdownOnce sync.Once
18		wg           sync.WaitGroup
19	}
20	
21	// Push sends a list of jobs to the queue.
22	// Jobs pushed after Shutdown are discarded.
23	func (p *Pool) Push(jobs model.JobList) {
24		for _, job := range jobs {
25			select {
26			case p.queue <- job:
27			case <-p.shutdown:
28				return
29			}
30		}
31	}
32	
33	// Shutdown stops accepting new jobs and waits for all workers to finish their current jobs.
34	func (p *Pool) Shutdown() {
35		p.shutdownOnce.Do(func() {
36			close(p.shutdown)
37		})
38		p.wg.Wait()
39	}
40	
41	// NewPool creates a pool of background workers.
42	func NewPool(store *storage.Storage, nbWorkers int) *Pool {
43		workerPool := &Pool{
44			queue:    make(chan model.Job),
45			shutdown: make(chan struct{}),
46		}
47	
48		for i := range nbWorkers {
49			workerPool.wg.Add(1)
50			worker := &worker{id: i, store: store}
51			go worker.Run(workerPool.queue, workerPool.shutdown, &workerPool.wg)
52		}
53	
54		return workerPool
55	}
56

